/// The chip selects of `SPI1`'s devices, each already an output. [`Spi1::init`]
/// takes them all, so nothing transfers on `SPI1` before every chip select of
/// the bus is driven: an undriven chip select is a selected part (`AET-WO-4200`
/// F3).
pub struct Spi1Selects {
    /// `U4`'s, net `FLASH_CS`.
    pub pa0: PA0<Output>,
}

/// The devices on `SPI1`, in the specification's order: each reference,
/// upper-cased.
#[allow(non_camel_case_types)]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Spi1Device {
    /// `U4`, a `W25Q64JVxIQ`, chip select `PA0`.
    U4,
}

impl Spi1<Clocked> {
    /// Master mode with software slave select, 8-bit frames, mode 0, the solved
    /// baud rate (`MBR` 1: the 64000000 Hz kernel over 4), and the peripheral
    /// left disabled: each transfer enables it and disables it again.
    /// Every chip select of the bus is driven high first (deselected), whatever
    /// firmware did with it before.
    /// `CR1` (`SSI`, `SPE` clear), `CFG1` and `CFG2` are written whole, in that
    /// order, and none is read (`AET-WO-4230` D5): the configuration registers
    /// change only while `SPE` is 0 (RM0433 Rev 9 §50.11.1, p. 2216), and `SSI`
    /// is high before `MASTER` and `SSM` are, so no mode fault can arise
    /// (§50.5.2, p. 2184). Only with a [`ResetClock`]: its kernel clock is the
    /// reset clock's.
    pub fn init<R: Registers>(
        self,
        r: &mut R,
        _clock: &ResetClock,
        _sck: PA5<AlternateFunction<5>>,
        _mosi: PA7<AlternateFunction<5>>,
        _miso: PA6<AlternateFunction<5>>,
        _selects: Spi1Selects,
    ) -> Spi1<Enabled<()>> {
        r.write(TOKEN, Block::GpioA, 0x18, 0x00000001);
        r.write(TOKEN, Block::Spi1, 0x00, 0x00001000);
        r.write(TOKEN, Block::Spi1, 0x08, 0x10070007);
        r.write(TOKEN, Block::Spi1, 0x0c, 0x84400000);
        Spi1 { _state: PhantomData }
    }
}

impl Spi1<Enabled<()>> {
    /// Selects `device` (its chip select low) and only it, writes `write`, then
    /// reads `read` while it clocks out `0x00`; then disables the peripheral and
    /// deselects the device, also after a wait that expired. Every frame is one
    /// byte, and every wait is bounded by [`SPI_WAIT_SPINS`]. Returns the bytes
    /// read, or why it gave up.
    pub fn transfer<R: Registers>(
        &mut self,
        r: &mut R,
        device: Spi1Device,
        write: &[u8],
        read: &mut [u8],
    ) -> Result<usize, SpiError> {
        self.transfer_within(r, device, write, read, SPI_WAIT_SPINS)
    }

    /// [`Self::transfer`] with its own bound on each wait, so the proof can use a
    /// small one.
    #[doc(hidden)]
    pub fn transfer_within<R: Registers>(
        &mut self,
        r: &mut R,
        device: Spi1Device,
        write: &[u8],
        read: &mut [u8],
        spins: u32,
    ) -> Result<usize, SpiError> {
        let frames = match u32::try_from(write.len() + read.len()) {
            Ok(n) if n > 0 && n <= SPI_MAX_FRAMES => n,
            _ => return Err(SpiError::Length),
        };
        let (port, select, deselect) = match device {
            Spi1Device::U4 => (Block::GpioA, 0x00010000, 0x00000001),
        };
        r.write(TOKEN, Block::Spi1, 0x04, frames);
        r.write(TOKEN, port, 0x18, select);
        r.write(TOKEN, Block::Spi1, 0x00, 0x00001001);
        r.write(TOKEN, Block::Spi1, 0x00, 0x00001201);
        let mut fail = false;
        for &byte in write {
            if spi_frame(r, Block::Spi1, byte, spins).is_none() {
                fail = true;
                break;
            }
        }
        let mut got = 0;
        if !fail {
            for slot in read.iter_mut() {
                match spi_frame(r, Block::Spi1, 0x00, spins) {
                    Some(byte) => *slot = byte,
                    None => {
                        fail = true;
                        break;
                    }
                }
                got += 1;
            }
        }
        // A master is disabled only once `EOT` is set (RM0433 Rev 9 §50.4.12,
        // p. 2177, step 1), and `EOTC` clears it.
        let mut ended = fail;
        let mut n = 0;
        while !ended && n < spins {
            ended = r.read(TOKEN, Block::Spi1, 0x14) & 0x00000008 != 0;
            n += 1;
        }
        // ES0392 Rev 16 §2.22.6: at least one SCK period between `EOT` and
        // `SPE` = 0, 5 reads of `SR` at the fastest core clock, as 1 of
        // [`spi_sr_round`].
        if ended && !fail {
            let mut k = 0;
            while k < 1 {
                spi_sr_round(r, Block::Spi1);
                k += 1;
            }
        }
        r.write(TOKEN, Block::Spi1, 0x18, 0x00000008);
        r.write(TOKEN, Block::Spi1, 0x00, 0x00001000);
        r.write(TOKEN, port, 0x18, deselect);
        if fail {
            Err(SpiError::Rxp)
        } else if !ended {
            Err(SpiError::Eot)
        } else {
            Ok(got)
        }
    }
}

/// `USART1`: serial port `CONSOLE` (specification index 0), TX `PA9`, RX
/// `PA10`, 115200 baud 8N1. It is configured only from `Clocked`, only on its two
/// solved pins, each in its solved function, only with a [`ResetClock`], and
/// once; it sends and receives only once configured.
pub struct Usart1<S> {
    _state: PhantomData<S>,
}

impl Usart1<Clocked> {
    /// The solved framing, every register written in full and none read, the
    /// USART disabled until the last write: `BRR`, `CR2`, `CR1` with `UE` clear
    /// and FIFO mode on (`FIFOEN`), then `CR1` with `UE`. `CR3` and `PRESC` keep
    /// their reset values (`OVER8` and `ONEBIT` 0, the kernel clock undivided),
    /// which the solved `BRR` assumes.
    pub fn configure<R: Registers>(
        self,
        r: &mut R,
        _clock: &ResetClock,
        _tx: PA9<AlternateFunction<7>>,
        _rx: PA10<AlternateFunction<7>>,
    ) -> Usart1<Enabled<()>> {
        r.write(TOKEN, Block::Usart1, 0x0c, 0x0000022c); // BRR
        r.write(TOKEN, Block::Usart1, 0x04, 0x00000000); // CR2
        r.write(TOKEN, Block::Usart1, 0x00, 0x2000000c); // CR1
        r.write(TOKEN, Block::Usart1, 0x00, 0x2000000d); // CR1 | UE
        Usart1 { _state: PhantomData }
    }
}

impl Usart1<Enabled<()>> {
    /// Waits at most [`USART_WAIT_SPINS`] reads of `ISR` for `TXFNF`, then writes
    /// `byte` to `TDR`; or gives up, writing nothing.
    pub fn send<R: Registers>(&mut self, r: &mut R, byte: u8) -> Result<(), TxeTimeout> {
        if usart_wait(r, Block::Usart1, 0x00000080, USART_WAIT_SPINS) {
            r.write(TOKEN, Block::Usart1, 0x28, u32::from(byte));
            Ok(())
        } else {
            Err(TxeTimeout)
        }
    }

    /// Waits at most `polls` reads of `ISR` for `RXFNE`, then reads the low byte of
    /// `RDR`; `None`, with `RDR` unread, when nothing arrived.
    pub fn receive<R: Registers>(&mut self, r: &mut R, polls: u32) -> Option<u8> {
        if usart_wait(r, Block::Usart1, 0x00000020, polls) {
            Some(u8::try_from(r.read(TOKEN, Block::Usart1, 0x24) & 0xFF).unwrap_or(0))
        } else {
            None
        }
    }
}

/// The clock gates, one method per solved port and peripheral.
pub struct Rcc {
    _private: (),
}

impl Rcc {
    /// `RCC_AHB4ENR` bit 0. Then the register read back, so the write is not
    /// pending in a write buffer, and a dummy read of the block, which takes the
    /// two clock periods an enable may need (RM0433 Rev 9 §8.5.10, p. 372, steps b
    /// and d).
    pub fn enable_gpioa<R: Registers>(&mut self, r: &mut R, _gated: GpioA<Gated>) -> GpioA<Clocked> {
        r.modify(TOKEN, Block::Rcc, 0x0e0, |v| v | 0x00000001);
        let _ = r.read(TOKEN, Block::Rcc, 0x0e0);
        let _ = r.read(TOKEN, Block::GpioA, 0x00);
        GpioA { _state: PhantomData }
    }

    /// `RCC_AHB4ENR` bit 1. Then the register read back, so the write is not
    /// pending in a write buffer, and a dummy read of the block, which takes the
    /// two clock periods an enable may need (RM0433 Rev 9 §8.5.10, p. 372, steps b
    /// and d).
    pub fn enable_gpiob<R: Registers>(&mut self, r: &mut R, _gated: GpioB<Gated>) -> GpioB<Clocked> {
        r.modify(TOKEN, Block::Rcc, 0x0e0, |v| v | 0x00000002);
        let _ = r.read(TOKEN, Block::Rcc, 0x0e0);
        let _ = r.read(TOKEN, Block::GpioB, 0x00);
        GpioB { _state: PhantomData }
    }

    /// `RCC_APB1LENR` bit 21. Then the register read back, so the write is not
    /// pending in a write buffer, and a dummy read of the block, which takes the
    /// two clock periods an enable may need (RM0433 Rev 9 §8.5.10, p. 372, steps b
    /// and d).
    pub fn enable_i2c1<R: Registers>(&mut self, r: &mut R, _gated: I2c1<Gated>) -> I2c1<Clocked> {
        r.modify(TOKEN, Block::Rcc, 0x0e8, |v| v | 0x00200000);
        let _ = r.read(TOKEN, Block::Rcc, 0x0e8);
        let _ = r.read(TOKEN, Block::I2c1, 0x00);
        I2c1 { _state: PhantomData }
    }

    /// `RCC_APB2ENR` bit 12. Then the register read back, so the write is not
    /// pending in a write buffer, and a dummy read of the block, which takes the
    /// two clock periods an enable may need (RM0433 Rev 9 §8.5.10, p. 372, steps b
    /// and d).
    /// Only once its kernel clock is selected ([`SpiKernels`]).
    pub fn enable_spi1<R: Registers>(&mut self, r: &mut R, _gated: Spi1<Gated>, _kernels: &SpiKernels) -> Spi1<Clocked> {
        r.modify(TOKEN, Block::Rcc, 0x0f0, |v| v | 0x00001000);
        let _ = r.read(TOKEN, Block::Rcc, 0x0f0);
        let _ = r.read(TOKEN, Block::Spi1, 0x00);
        Spi1 { _state: PhantomData }
    }

    /// `RCC_APB2ENR` bit 4. Then the register read back, so the write is not
    /// pending in a write buffer (RM0433 Rev 9 §8.5.10, p. 372, step b).
    pub fn enable_usart1<R: Registers>(&mut self, r: &mut R, _gated: Usart1<Gated>) -> Usart1<Clocked> {
        r.modify(TOKEN, Block::Rcc, 0x0f0, |v| v | 0x00000010);
        let _ = r.read(TOKEN, Block::Rcc, 0x0f0);
        Usart1 { _state: PhantomData }
    }

    /// A [`ResetClock`], when each of these fields holds 0, its reset value
    /// (RM0433 Rev 9 §8.7.2, §8.7.7–8.7.10, §8.7.19–8.7.22). Reads the seven registers
    /// and writes nothing.
    /// - `RCC_CR`: `HSIDIV`.
    /// - `RCC_CFGR`: `SWS`, `TIMPRE`.
    /// - `RCC_D1CFGR`: `D1CPRE`, `D1PPRE`, `HPRE`.
    /// - `RCC_D2CFGR`: `D2PPRE1`, `D2PPRE2`.
    /// - `RCC_D1CCIPR`: `CKPERSEL`.
    /// - `RCC_D2CCIP1R`: `SPI123SEL`, `SPI45SEL`.
    /// - `RCC_D2CCIP2R`: `USART16SEL`, `USART28SEL`, `I2C123SEL`.
    pub fn reset_clock<R: Registers>(&self, r: &mut R) -> Result<ResetClock, NotResetClock> {
        let cr = r.read(TOKEN, Block::Rcc, 0x000);
        let cfgr = r.read(TOKEN, Block::Rcc, 0x010);
        let d1cfgr = r.read(TOKEN, Block::Rcc, 0x018);
        let d2cfgr = r.read(TOKEN, Block::Rcc, 0x01c);
        let d1ccipr = r.read(TOKEN, Block::Rcc, 0x04c);
        let d2ccip1r = r.read(TOKEN, Block::Rcc, 0x050);
        let d2ccip2r = r.read(TOKEN, Block::Rcc, 0x054);
        if cr & 0x00000018 == 0 && cfgr & 0x00008038 == 0 && d1cfgr & 0x00000f7f == 0 && d2cfgr & 0x00000770 == 0 && d1ccipr & 0x30000000 == 0 && d2ccip1r & 0x00077000 == 0 && d2ccip2r & 0x0000303f == 0 {
            Ok(ResetClock { _private: () })
        } else {
            Err(NotResetClock)
        }
    }

    /// Selects each solved SPI controller's kernel clock, every select register
    /// written whole, every other field at its reset value, 0 (RM0433 Rev 9
    /// §8.7.20, §8.7.22), and none read: Renode 1.17.0 stores no selection.
    /// - `SPI1`: `per_ck` (HSI at `CKPERSEL`'s reset), 64000000 Hz.
    pub fn select_spi_kernels<R: Registers>(&mut self, r: &mut R, _clock: &ResetClock) -> SpiKernels {
        r.write(TOKEN, Block::Rcc, 0x050, 0x00004000); // D2CCIP1R
        SpiKernels { _private: () }
    }
}

/// The flash controller's registers: only `FLASH_OPTSR_CUR`, read once.
pub struct Flash {
    _private: (),
}

impl Flash {
    /// `FLASH_OPTSR_CUR`, read once, whole: its `BOR_LEV` (bits 3:2) is the
    /// brown-out level the option bytes hold (RM0433 Rev 9 §4.9.8, p. 212;
    /// `AET-WO-4230` §1.6). The firmware writes nothing to the flash controller:
    /// programming the option bytes is a factory step.
    pub fn option_status<R: Registers>(self, r: &mut R) -> u32 {
        r.read(TOKEN, Block::Flash, 0x1c)
    }
}

/// Everything on the board, once per program.
pub struct Board {
    pub rcc: Rcc,
    pub flash: Flash,
    pub gpioa: GpioA<Gated>,
    pub gpiob: GpioB<Gated>,
    pub i2c1: I2c1<Gated>,
    pub spi1: Spi1<Gated>,
    pub usart1: Usart1<Gated>,
}

static TAKEN: AtomicBool = AtomicBool::new(false);

impl Board {
    /// The board, the first time; `None` after that. The crate's one
    /// runtime check.
    pub fn take() -> Option<Board> {
        if TAKEN.swap(true, Ordering::AcqRel) {
            return None;
        }
        Some(Board {
            rcc: Rcc { _private: () },
            flash: Flash { _private: () },
            gpioa: GpioA { _state: PhantomData },
            gpiob: GpioB { _state: PhantomData },
            i2c1: I2c1 { _state: PhantomData },
            spi1: Spi1 { _state: PhantomData },
            usart1: Usart1 { _state: PhantomData },
        })
    }
}
